/// Domain entity categories generated by runtime implementations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IdKind {
    /// Correlation identifier for one externally initiated operation.
    Trace,
    /// Persisted session identifier.
    Session,
    /// Agent run identifier.
    Run,
    /// Model turn identifier.
    Turn,
    /// Transcript message identifier.
    Message,
    /// Persisted entry identifier.
    Entry,
    /// Persisted operation-record identifier.
    Record,
    /// Persisted pending-message identifier.
    Queue,
}

impl IdKind {
    /// Returns the readable prefix used by generated identifiers.
    #[must_use]
    pub const fn prefix(self) -> &'static str {
        match self {
            Self::Trace => "trace",
            Self::Session => "session",
            Self::Run => "run",
            Self::Turn => "turn",
            Self::Message => "message",
            Self::Entry => "entry",
            Self::Record => "record",
            Self::Queue => "queue",
        }
    }
}

/// Supplies raw unique identifiers while protocol newtypes enforce their domain.
pub trait IdGenerator: Send + Sync {
    /// Generates one non-empty identifier for the selected entity category.
    fn next(&self, kind: IdKind) -> String;
}
